#!/bin/bash
# cc.sh <src> <out> [extra -D...]: malloc-mapping.c with the sdkm13b runtime's exact ninja flags (build.ninja:62-66)
: "${CAPSTONE_WORK:=/mnt/hdd/$USER/capstone}" "${CAPSTONE_LLVM:=$HOME/dev/llvm-capstone}"
src=$1 out=$2; shift 2
exec ${CAPSTONE_WORK}/llvm-c4/bin/clang -DCAPSTONE_APPLICATION_CONTEXTS=15 -DCAPSTONE_APPLICATION_EXCHANGE_BYTES=262144 -DCAPSTONE_APPLICATION_HEAP_BYTES=0 -DCAPSTONE_CONTEXT_ARENA_BYTES=65536 -DCAPSTONE_DOMREQ_DATA=2162944 -DCAPSTONE_DOMREQ_STACK=1048576 -DCAPSTONE_HEAP_LIFETIMES=1 -DCAPSTONE_HEAP_MAPPING_REUSE=1 -DCAPSTONE_HEAP_OBJECT_BOUNDS=1 -DCAPSTONE_HEAP_SCRUB_FREE=0 -DCAPSTONE_LEVEL0_ARENA_BYTES=67108864 -DCAPSTONE_RUNTIME_VIRTUAL=1 -D_XOPEN_SOURCE=700 "$@" -I${CAPSTONE_WORK}/wt-mrhwm/capstone/sublet -I${CAPSTONE_WORK}/wt-mrhwm/capstone/runtime/include -Xclang -target-feature -Xclang +m -Xclang -target-feature -Xclang +a -ffreestanding -fno-builtin -nostdinc -isystem ${CAPSTONE_WORK}/perf/alean/sdkm13b/musl-src/musl-1.2.5/arch/capstone64 -isystem ${CAPSTONE_WORK}/perf/alean/sdkm13b/musl-src/musl-1.2.5/arch/generic -isystem ${CAPSTONE_WORK}/perf/alean/sdkm13b/musl-src/musl-1.2.5/obj/include -isystem ${CAPSTONE_WORK}/perf/alean/sdkm13b/musl-src/musl-1.2.5/include -isystem ${CAPSTONE_WORK}/llvm-c4/lib/clang/22/include -O1 -std=gnu11 -mllvm -capstone-gp-free -mllvm -capstone-image-gp -Xclang -target-feature -Xclang +f -Xclang -target-feature -Xclang +d -Xclang -target-abi -Xclang lp64 -Xclang -target-feature -Xclang +movc-keeps-integer-source -ffunction-sections -fdata-sections -fjump-tables -fomit-frame-pointer --target=capstone64-unknown-elf -c $src -o $out
